using System.Collections.Concurrent;
using System.Reflection;
using System.Runtime.ExceptionServices;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace PutridParrot.Mediator;

/// <summary>
/// Mediator implementation that uses source-generated dispatcher for optimal performance.
/// Falls back to reflection-based dispatch if generated dispatcher is not available.
/// </summary>
/// <remarks>
/// This mediator uses the IRequestDispatcher (generated by source generator) to invoke handlers
/// directly without reflection. If the dispatcher is not available, it falls back to reflection.
/// For logging, use <see cref="LoggingPipelineBehavior{TRequest,TResponse}"/> or call
/// <see cref="LoggingExtensions.AddMediatorLogging(Microsoft.Extensions.DependencyInjection.IServiceCollection)"/>.
/// </remarks>
public class Mediator : IMediator
{
    private readonly IServiceProvider _serviceProvider;
    private readonly IRequestDispatcher? _dispatcher;
    private readonly IStreamDispatcher? _streamDispatcher;
    private readonly MediatorOptions _options;
    private readonly ILogger<Mediator>? _logger;

    // Strongly-typed pipeline invokers, built once per (request, response) type pair
    private static readonly ConcurrentDictionary<(Type Request, Type Response), Delegate> PipelineInvokers = new();

    // Strongly-typed notification publishers, built once per notification type
    private static readonly ConcurrentDictionary<Type, Func<Mediator, INotification, CancellationToken, Task>> NotificationPublishers = new();

    /// <summary>
    /// Initializes a new instance of the Mediator class.
    /// </summary>
    /// <param name="serviceProvider">The service provider to resolve handlers.</param>
    /// <param name="dispatcher">Optional generated dispatcher for fast invocation.</param>
    /// <param name="streamDispatcher">Optional generated stream dispatcher for fast streaming.</param>
    /// <param name="options">Optional runtime options; defaults are used when not supplied.</param>
    /// <param name="logger">Optional logger, used for notification handler failures with <see cref="NotificationErrorHandling.LogAndContinue"/>.</param>
    public Mediator(
        IServiceProvider serviceProvider,
        IRequestDispatcher? dispatcher = null,
        IStreamDispatcher? streamDispatcher = null,
        MediatorOptions? options = null,
        ILogger<Mediator>? logger = null)
    {
        _serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
        _dispatcher = dispatcher;
        _streamDispatcher = streamDispatcher;
        _options = options ?? new MediatorOptions();
        _logger = logger;
    }

    /// <summary>
    /// Sends a request to its handler, executing any registered pipeline behaviors.
    /// </summary>
    public async Task<TResponse> Send<TResponse>(IRequest<TResponse> request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        
        var requestType = request.GetType();
        var handlerType = typeof(IRequestHandler<,>).MakeGenericType(requestType, typeof(TResponse));
        
        var handler = _serviceProvider.GetService(handlerType);
        
        if (handler == null)
        {
            throw new InvalidOperationException($"No handler registered for request type {requestType.FullName}");
        }

        // Define the handler delegate
        Func<Task<TResponse>> handlerDelegate = async () =>
        {
            // Use generated dispatcher if available (fast path)
            if (_dispatcher != null && _dispatcher.CanDispatch(requestType))
            {
                return await _dispatcher.Dispatch(request, handler, cancellationToken);
            }

            // Fallback to reflection (slow path)
            var handleMethod = handlerType.GetMethod(nameof(IRequestHandler<,>.Handle));
            var result = handleMethod!.Invoke(handler, [request, cancellationToken]);
            
            if (result is Task<TResponse> task)
            {
                return await task;
            }
            
            throw new InvalidOperationException($"Handler for {requestType.FullName} did not return a Task<{typeof(TResponse).FullName}>");
        };

        // Wrap the handler in any registered pipeline behaviors
        var invoker = (Func<IServiceProvider, IRequest<TResponse>, Func<Task<TResponse>>, CancellationToken, Task<TResponse>>)
            PipelineInvokers.GetOrAdd((requestType, typeof(TResponse)), static key =>
                ExecuteWithBehaviorsMethod
                    .MakeGenericMethod(key.Request, key.Response)
                    .CreateDelegate<Func<IServiceProvider, IRequest<TResponse>, Func<Task<TResponse>>, CancellationToken, Task<TResponse>>>());

        return await invoker(_serviceProvider, request, handlerDelegate, cancellationToken);
    }

    private static readonly MethodInfo ExecuteWithBehaviorsMethod =
        typeof(Mediator).GetMethod(nameof(ExecuteWithBehaviors), BindingFlags.NonPublic | BindingFlags.Static)!;

    private static Task<TResponse> ExecuteWithBehaviors<TRequest, TResponse>(
        IServiceProvider serviceProvider,
        IRequest<TResponse> request,
        Func<Task<TResponse>> handlerDelegate,
        CancellationToken cancellationToken)
        where TRequest : IRequest<TResponse>
    {
        var behaviors = serviceProvider.GetServices<IPipelineBehavior<TRequest, TResponse>>().ToArray();

        if (behaviors.Length == 0)
        {
            return handlerDelegate();
        }

        // Build the pipeline from the inside out so the first registered behavior runs first
        var typedRequest = (TRequest)request;
        RequestHandlerDelegate<TResponse> pipeline = () => handlerDelegate();

        for (var i = behaviors.Length - 1; i >= 0; i--)
        {
            var behavior = behaviors[i];
            var next = pipeline;
            pipeline = () => behavior.Handle(typedRequest, next, cancellationToken);
        }

        return pipeline();
    }
    
    /// <summary>
    /// Sends a request that has no response to its handler.
    /// </summary>
    /// <param name="request">The request to send.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <exception cref="InvalidOperationException">No handler is registered for the request type.</exception>
    public async Task Send(IRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        
        var requestType = request.GetType();
        var handlerType = typeof(IRequestHandler<>).MakeGenericType(requestType);
        
        var handler = _serviceProvider.GetService(handlerType);
        
        if (handler == null)
        {
            throw new InvalidOperationException($"No handler registered for request type {requestType.FullName}");
        }

        // Use generated dispatcher if available (fast path)
        if (_dispatcher != null && _dispatcher.CanDispatch(requestType))
        {
            await _dispatcher.Dispatch(request, handler, cancellationToken);
            return;
        }

        // Fallback to reflection (slow path)
        var handleMethod = handlerType.GetMethod(nameof(IRequestHandler<>.Handle));
        var result = handleMethod!.Invoke(handler, [request, cancellationToken]);
        
        if (result is Task task)
        {
            await task;
            return;
        }
        
        
        throw new InvalidOperationException($"Handler for {requestType.FullName} did not return a Task");
    }
    
    /// <summary>
    /// Publishes a notification to all registered handlers, one at a time in registration order.
    /// Handler exceptions are handled according to <see cref="MediatorOptions.NotificationErrorHandling"/>.
    /// </summary>
    /// <param name="notification">The notification to publish.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    public async Task Publish(INotification notification, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(notification);
        
        var publisher = NotificationPublishers.GetOrAdd(notification.GetType(), static notificationType =>
            PublishToHandlersMethod
                .MakeGenericMethod(notificationType)
                .CreateDelegate<Func<Mediator, INotification, CancellationToken, Task>>());

        await publisher(this, notification, cancellationToken);
    }

    private static readonly MethodInfo PublishToHandlersMethod =
        typeof(Mediator).GetMethod(nameof(PublishToHandlers), BindingFlags.NonPublic | BindingFlags.Static)!;

    private static async Task PublishToHandlers<TNotification>(
        Mediator mediator,
        INotification notification,
        CancellationToken cancellationToken)
        where TNotification : INotification
    {
        var typedNotification = (TNotification)notification;
        var errorHandling = mediator._options.NotificationErrorHandling;
        List<Exception>? exceptions = null;

        // Handlers run one at a time, in registration order
        foreach (var handler in mediator._serviceProvider.GetServices<INotificationHandler<TNotification>>())
        {
            try
            {
                await handler.Handle(typedNotification, cancellationToken);
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                throw;
            }
            catch (Exception ex) when (errorHandling != NotificationErrorHandling.StopOnFirstException)
            {
                if (errorHandling == NotificationErrorHandling.LogAndContinue)
                {
                    mediator._logger?.LogError(ex, "Notification handler {Handler} failed handling {Notification}",
                        handler.GetType().FullName, typeof(TNotification).FullName);
                }
                else
                {
                    (exceptions ??= []).Add(ex);
                }
            }
        }

        if (exceptions is { Count: 1 })
        {
            ExceptionDispatchInfo.Capture(exceptions[0]).Throw();
        }
        else if (exceptions is { Count: > 1 })
        {
            throw new AggregateException(
                $"{exceptions.Count} notification handlers failed handling {typeof(TNotification).FullName}", exceptions);
        }
    }

    /// <summary>
    /// Creates a stream of responses from the handler registered for the streaming request.
    /// </summary>
    /// <param name="request">The streaming request.</param>
    /// <param name="cancellationToken">Cancellation token used while enumerating the stream.</param>
    /// <exception cref="InvalidOperationException">No stream handler is registered for the request type.</exception>
    public async IAsyncEnumerable<TResponse> CreateStream<TResponse>(
        IStreamRequest<TResponse> request, 
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        
        var requestType = request.GetType();
        var handlerType = typeof(IStreamRequestHandler<,>).MakeGenericType(requestType, typeof(TResponse));
        
        var handler = _serviceProvider.GetService(handlerType);
        
        if (handler == null)
        {
            throw new InvalidOperationException($"No stream handler registered for request type {requestType.FullName}");
        }

        // Use generated stream dispatcher if available (fast path)
        if (_streamDispatcher != null && _streamDispatcher.CanDispatch(requestType))
        {
            await foreach (var item in _streamDispatcher.DispatchStream(request, handler, cancellationToken))
            {
                yield return item;
            }
            yield break;
        }

        // Fallback to reflection (slow path)
        var handleMethod = handlerType.GetMethod(nameof(IStreamRequestHandler<IStreamRequest<TResponse>, TResponse>.Handle));
        var result = handleMethod!.Invoke(handler, [request, cancellationToken]);
        
        if (result is IAsyncEnumerable<TResponse> stream)
        {
            await foreach (var item in stream.WithCancellation(cancellationToken))
            {
                yield return item;
            }
        }
        else
        {
            throw new InvalidOperationException($"Handler for {requestType.FullName} did not return an IAsyncEnumerable<{typeof(TResponse).FullName}>");
        }
    }
}



